{"operationName":"PRODUCT_CATEGORY_NAMES_QUERY","variables":{"permalinks":["custom-stickers"],"isAlias":false},"query":"query PRODUCT_CATEGORY_NAMES_QUERY($permalinks: [String!]!, $isAlias: Boolean!) {
  productCategories(locale: "en", permalinks: $permalinks) @skip(if: $isAlias) {
    name
    permalink
    related {
      ... on Product {
        name
        permalink: permalink
        __typename
      }
      ... on ProductAlias {
        name
        aliasPermalink: permalink
        __typename
      }
      ... on ProductAliasCategory {
        name
        aliasCategoryPermalink: permalink
        __typename
      }
      __typename
    }
    products {
      name
      permalink
      __typename
    }
    __typename
  }
  productAliasCategories(locale: "en", permalinks: $permalinks) @include(if: $isAlias) {
    name
    permalink
    related {
      ... on Product {
        name
        permalink: permalink
        __typename
      }
      ... on ProductAlias {
        name
        aliasPermalink: permalink
        __typename
      }
      ... on ProductAliasCategory {
        name
        aliasCategoryPermalink: permalink
        __typename
      }
      __typename
    }
    aliases {
      name
      permalink
      product {
        name
        permalink
        __typename
      }
      __typename
    }
    __typename
  }
}"}

